      $result = $this->listUsecase->list($filter, $cursor);
      $value = ['items' => array_map(fn(TemplateVersionAttributes $item):TemplateVersionApiDTO => $this->mapTemplateVersion($request, $item), $result->values())];
      $nextLink = $this->nextLink( $result->cursor(), $params );
